const restorePageSubtree = `-- name: RestorePageSubtree :execrows
WITH RECURSIVE down (id, depth) AS (
  SELECT p.id, 0 FROM page p WHERE p.tenant_id = current_tenant_id() AND p.id = $4
  UNION ALL
  SELECT p.id, down.depth + 1 FROM page p JOIN down ON p.parent_id = down.id
   WHERE p.tenant_id = current_tenant_id() AND p.deleted_at = $3::timestamptz AND down.depth < 16
)
UPDATE page AS t SET deleted_at = NULL, updated_by = $1, updated_at = $2,
  version = t.version + 1
WHERE t.tenant_id = current_tenant_id() AND t.id IN (SELECT id FROM down)
  AND t.deleted_at = $3::timestamptz
`

type RestorePageSubtreeParams struct {
	By        pgtype.UUID
	At        pgtype.Timestamptz
	TrashedAt pgtype.Timestamptz
	ID        pgtype.UUID
}

// Brings back the page and the pages trashed with it - at the same moment - and not a page under
// it that was trashed on its own before.
func (q *Queries) RestorePageSubtree(ctx context.Context, arg RestorePageSubtreeParams) (int64, error) {
	result, err := q.db.Exec(ctx, restorePageSubtree,
		arg.By,
		arg.At,
		arg.TrashedAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const searchPages = `-- name: SearchPages :many
SELECT p.id, p.hub_id, p.parent_id, p.title, p.icon, p.updated_at,
       ts_rank_cd(p.search_document, q.query)::float8 AS rank,
       ts_headline(hubtask_text_config(p.content_language), p.body, q.query,
         'MaxFragments=1, MaxWords=24, MinWords=8, StartSel=«, StopSel=»')::text AS excerpt
FROM page p,
     LATERAL (SELECT websearch_to_tsquery(hubtask_text_config(p.content_language), $1::text)
                  || websearch_to_tsquery('simple', $1::text) AS query) q
WHERE p.tenant_id = current_tenant_id() AND p.hub_id = ANY($2::uuid[])
  AND p.deleted_at IS NULL AND p.archived_at IS NULL
  AND p.search_document @@ q.query
ORDER BY rank DESC, p.updated_at DESC, p.id
LIMIT $3
`

type SearchPagesParams struct {
	Text   string
	HubIds []pgtype.UUID
	Batch  int32
}

type SearchPagesRow struct {
	ID        pgtype.UUID
	HubID     pgtype.UUID
	ParentID  pgtype.UUID
	Title     string
	Icon      string
	UpdatedAt pgtype.Timestamptz
	Rank      float64
	Excerpt   string
}

// The pages a text finds in the spaces named, ranked; archived and trashed pages stay out.
func (q *Queries) SearchPages(ctx context.Context, arg SearchPagesParams) ([]SearchPagesRow, error) {
	rows, err := q.db.Query(ctx, searchPages, arg.Text, arg.HubIds, arg.Batch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchPagesRow{}
	for rows.Next() {
		var i SearchPagesRow
		if err := rows.Scan(
			&i.ID,
			&i.HubID,
			&i.ParentID,
			&i.Title,
			&i.Icon,
			&i.UpdatedAt,
			&i.Rank,
			&i.Excerpt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const trashPageSubtree = `-- name: TrashPageSubtree :execrows
WITH RECURSIVE down (id, depth) AS (
  SELECT p.id, 0 FROM page p WHERE p.tenant_id = current_tenant_id() AND p.id = $3
  UNION ALL
  SELECT p.id, down.depth + 1 FROM page p JOIN down ON p.parent_id = down.id
   WHERE p.tenant_id = current_tenant_id() AND p.deleted_at IS NULL AND down.depth < 16
)
UPDATE page AS t SET deleted_at = $1, updated_by = $2, updated_at = $1,
  version = t.version + 1
WHERE t.tenant_id = current_tenant_id() AND t.id IN (SELECT id FROM down) AND t.deleted_at IS NULL
`

type TrashPageSubtreeParams struct {
	At pgtype.Timestamptz
	By pgtype.UUID
	ID pgtype.UUID
}

// Marks the page and the pages under it trashed at one moment, which is what a restore brings back.
func (q *Queries) TrashPageSubtree(ctx context.Context, arg TrashPageSubtreeParams) (int64, error) {
	result, err := q.db.Exec(ctx, trashPageSubtree, arg.At, arg.By, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updatePage = `-- name: UpdatePage :execrows
UPDATE page SET
  parent_id = $1, title = $2, body = $3,
  icon = $4, order_key = $5, template = $6,
  content_language = $7, owner_id = $8,
  verified_until = $9, verified_at = $10,
  verified_by = $11, archived_at = $12,
  deleted_at = $13, updated_by = $14,
  updated_at = $15, version = version + 1
WHERE tenant_id = current_tenant_id() AND id = $16 AND version = $17
`

type UpdatePageParams struct {
	ParentID        pgtype.UUID
	Title           string
	Body            string
	Icon            string
	OrderKey        string
	Template        bool
	ContentLanguage *string
	OwnerID         pgtype.UUID
	VerifiedUntil   pgtype.Timestamptz
	VerifiedAt      pgtype.Timestamptz
	VerifiedBy      pgtype.UUID
	ArchivedAt      pgtype.Timestamptz
	DeletedAt       pgtype.Timestamptz
	UpdatedBy       pgtype.UUID
	UpdatedAt       pgtype.Timestamptz
	ID              pgtype.UUID
	ExpectedVersion int32
}

// Optimistic: zero rows is a page changed meanwhile.
func (q *Queries) UpdatePage(ctx context.Context, arg UpdatePageParams) (int64, error) {
	result, err := q.db.Exec(ctx, updatePage,
		arg.ParentID,
		arg.Title,
		arg.Body,
		arg.Icon,
		arg.OrderKey,
		arg.Template,
		arg.ContentLanguage,
		arg.OwnerID,
		arg.VerifiedUntil,
		arg.VerifiedAt,
		arg.VerifiedBy,
		arg.ArchivedAt,
		arg.DeletedAt,
		arg.UpdatedBy,
		arg.UpdatedAt,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

